+package com.example.pricing;
+
+import java.util.Map;
+import java.util.SortedMap;
+import java.util.TreeMap;
+
+public final class MinPriceConfiguration {
+    private MinPriceConfiguration() {}
+
+    /** Parses MIN_PRICE_BY_TIER, e.g. "ECONOMY:10,STANDARD:20,PREMIUM:40". */
+    public static SortedMap<Tier, Double> parseMinPriceByTier(Map<String, String> configMap) {
+        String raw = configMap.get("MIN_PRICE_BY_TIER");
+        if (raw == null || raw.isBlank()) {
+            throw new IllegalArgumentException("Missing MIN_PRICE_BY_TIER job configuration");
+        }
+        SortedMap<Tier, Double> byTier = new TreeMap<>();
+        for (String entry : raw.split(",")) {
+            String[] parts = entry.split(":");
+            if (parts.length != 2) {
+                throw new IllegalArgumentException("Malformed MIN_PRICE_BY_TIER entry: " + entry);
+            }
+            byTier.put(Tier.fromConfigurationValue(parts[0]), Double.valueOf(parts[1].trim()));
+        }
+        return byTier;
+    }
+}
